function questionKey(item){return item.id+':'+item.index}
function initialiseQuestionHistory(){if(!profile.questionSeen||typeof profile.questionSeen!=='object'||Array.isArray(profile.questionSeen))profile.questionSeen={};profile.questionSerial=Math.max(Number(profile.questionSerial)||0,...Object.values(profile.questionSeen).filter(Number.isFinite),0)}
function weaveQuestions(groups){const result=[];let lastFamily=null;while(groups.some(g=>g.length)){for(const list of shuffle(groups.filter(g=>g.length))){let i=list.findIndex(item=>!item.q[6]||item.q[6]!==lastFamily);if(i<0)i=0;const [item]=list.splice(i,1);result.push(item);lastFamily=item.q[6]||null}}return result}
function buildQuestionDeck(subject){const ids=Array.isArray(subject)?subject:subject==='mixed'?SUBJECTS.map(s=>s.id):[subject],fresh=[],old=[];for(const id of ids){const items=BANK[id].map((q,index)=>({id,index,q}));fresh.push(shuffle(items.filter(item=>!profile.questionSeen[questionKey(item)])));old.push(...items.filter(item=>profile.questionSeen[questionKey(item)]))}old.sort((a,b)=>profile.questionSeen[questionKey(a)]-profile.questionSeen[questionKey(b)]);return [...weaveQuestions(fresh),...old]}
function noteQuestionShown(item){profile.questionSeen[questionKey(item)]=++profile.questionSerial;save()}
function exploredQuestions(){return Object.keys(profile.questionSeen).filter(key=>{const [id,index]=key.split(':');return BANK[id]?.[index]}).length}
